def test_parse_sample():
    summary = parse_vl06o_raw_text(SAMPLE_DATA, transport_doc="3417089", cantidad_pallet=2)
    assert summary.numero_transporte == "3417089"
    assert summary.cliente == "COMERCIAL DOLLINCO S.A."
    assert summary.total_skus == 35
    assert summary.cantidad_pallet == 2
    assert summary.semana == "Semana 36"
    assert len(summary.items) == 35
    
    first = summary.items[0]
    assert first.sku == "3071"
    assert first.descripcion == "PATE TERNERA 160 Gr.(x10)"
    assert first.cantidad_pedido == 3
    assert first.umv == "CJ"
    assert first.fecha == "02-sept"
    assert first.documento_transporte == "3417089"
    print("Test passed successfully! Total items:", len(summary.items))

if __name__ == "__main__":
    test_parse_sample()
